import mq3.client.ui_login as l
import mq3.client.ui_qmenu as q
function req(ok,label) if not ok then return error(7993,"login: "+label) end if;return 1 end function
function main(args) count=0;s=l.create(false);l.Login_MenuInit(s);count=count+req(len(s.menu.items)==7 and s.frame.name==l.LOGIN_FRAME,"menu and frame");count=count+req(s.name.string=="NAME" and s.password.string=="PASSWORD" and s.login.string=="LOGIN" and s.cancel.string=="CANCEL","labels");count=count+req(s.nameBox.widthInChars==16 and s.nameBox.maxchars==16 and s.passwordBox.maxchars==16,"field bounds");count=count+req(not l.Login_MenuEvent(s,l.ID_LOGIN,1) and len(s.actions)==1,"inactive event ignored");s.nameBox.buffer="Player!bad";s.passwordBox.buffer="pw-ignored";count=count+req(l.Login_MenuEvent(s,l.ID_LOGIN,q.QM_ACTIVATED) and s.forcedOff,"login event");count=count+req(s.actions[len(s.actions)-2].kind=="login" and s.actions[len(s.actions)-2].text=="Player" and s.actions[len(s.actions)-2].text2=="pw","typed credentials");c=l.create(false);l.Login_MenuInit(c);count=count+req(l.Login_MenuEvent(c,l.ID_CANCEL,q.QM_ACTIVATED) and c.popped,"cancel pop");live=l.create(false);l.UI_LoginMenu(live);count=count+req(live.pushed and live.actions[len(live.actions)-1].kind=="push-menu","menu push");silent=l.create(true);l.Login_Cache(silent);count=count+req(not silent.actions[0].dispatched,"suppression");print("PASS: "+str(count)+" UI login contracts");return 0 end function
